/**
 * Anti-rot guard for the inventory.
 *
 * docs/inventory.json is generated by tools/inventory.mjs. A generated artifact
 * that nothing checks becomes wrong silently, so this asserts the two properties
 * that make it trustworthy:
 *
 *   1. it was generated from the revision this evidence claims, and
 *   2. every name it lists is genuinely importable from the package root.
 *
 * (2) is the one that matters: it is what turns "I listed some exports" into
 * "these exports exist", and it fails loudly if a family is renamed or dropped.
 */
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import * as reactUi from "../../../packages/react-ui/src/index";

type Member = { name: string; kind: string; at: { file: string; line: number } | null };
type FamilyInfo = { exported: boolean; members: Member[] };
type Inventory = {
  revision: string;
  totalRootExports: number;
  scope: Record<string, Record<string, FamilyInfo>>;
  dependencyOnly: Record<string, FamilyInfo>;
  adjacentUnclaimed: Record<string, FamilyInfo>;
  discrepancies: string[];
};

const OWNED = path.resolve(__dirname, "..");
const REPO = path.resolve(OWNED, "../..");
const inventory: Inventory = JSON.parse(
  readFileSync(path.join(OWNED, "docs/inventory.json"), "utf8"),
);

const allFamilies = (): Array<[string, FamilyInfo]> => [
  ...Object.values(inventory.scope).flatMap((group) => Object.entries(group)),
  ...Object.entries(inventory.dependencyOnly),
  ...Object.entries(inventory.adjacentUnclaimed),
];

describe("inventory provenance", () => {
  it("was generated from the revision currently checked out", () => {
    const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: REPO }).toString().trim();
    expect(inventory.revision).toBe(head);
  });

  it("records no unresolved discrepancies", () => {
    expect(inventory.discrepancies).toEqual([]);
  });

  it("covers every family group #31 names", () => {
    expect(Object.keys(inventory.scope).sort()).toEqual([
      "citations/sources",
      "images",
      "table",
      "text/presentation",
    ]);
  });
});

describe("every inventoried value export is importable from the package root", () => {
  const runtime = reactUi as unknown as Record<string, unknown>;

  for (const [family, info] of allFamilies()) {
    const values = info.members.filter((m) => m.kind === "value");
    if (!values.length) continue;

    it(`${family}: ${values.length} value export(s) resolve`, () => {
      const missing = values.filter((m) => !(m.name in runtime)).map((m) => m.name);
      expect(missing).toEqual([]);
    });
  }
});

describe("inventoried declaration sites exist", () => {
  it("every member points at a real file", () => {
    const bad: string[] = [];
    for (const [family, info] of allFamilies()) {
      for (const member of info.members) {
        if (!member.at) {
          bad.push(`${family}.${member.name} has no declaration site`);
          continue;
        }
        try {
          readFileSync(path.join(REPO, member.at.file), "utf8");
        } catch {
          bad.push(`${family}.${member.name} -> missing ${member.at.file}`);
        }
      }
    }
    expect(bad).toEqual([]);
  });

  it("every in-scope member is declared under packages/react-ui", () => {
    // Guards against an inventory that accidentally attributes a react-ui-core
    // symbol to the legacy baseline, which would make the evidence misleading.
    for (const group of Object.values(inventory.scope)) {
      for (const [family, info] of Object.entries(group)) {
        for (const member of info.members) {
          expect(
            member.at?.file.startsWith("packages/react-ui/src/"),
            `${family}.${member.name} is declared at ${member.at?.file}`,
          ).toBe(true);
        }
      }
    }
  });
});
